/**
 * Holds every favicon face as a PNG, rendered from the source artwork in
 * favicon-artwork.ts. Generated by `deno task regenerate-favicons`, which
 * overwrites whatever is here.
 */

function decodePng(encoded: string): Uint8Array {
  return Uint8Array.fromBase64(encoded);
}

